 "content": "def transform(grid):
    """Reconstruct the hidden row/column of repeated n×n motifs.

    The local motif is also the occupancy mask for the n×n array of motifs.
    The 3-colored strip hides one macro row or column. Restore motif copies at
    occupied macro coordinates, and mark each copy at its macro coordinate.
    """
    h, w = len(grid), len(grid[0])
    n = next((k for k in range(1, 31) if h == w == k * k + k - 1), None)
    if n is None:
        raise ValueError("expected a square n-by-n motif array with one-cell gutters")
    pitch = n + 1

    motif = None
    for tr in range(n):
        for tc in range(n):
            tile = [row[tc * pitch:tc * pitch + n]
                    for row in grid[tr * pitch:tr * pitch + n]]
            if any(v == 2 for row in tile for v in row):
                motif = [[1 if v == 2 else 0 for v in row] for row in tile]
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError("no visible motif found")

    out = [[0] * w for _ in range(h)]
    for tr in range(n):
        for tc in range(n):
            if motif[tr][tc]:
                r0, c0 = tr * pitch, tc * pitch
                for dr in range(n):
                    for dc in range(n):
                        if motif[dr][dc]:
                            out[r0 + dr][c0 + dc] = 2
                # Mark the cell indexed by this motif's position in the array.
                out[r0 + tr][c0 + tc] = 8
    return out
